/*
  與「主導航列」有關的樣式
*/
nav {
  box-shadow: 0px 0rem 0.2rem #aaa;
  /* navbar.css */
}
nav .navbar-brand {
  color: rgba(18, 52, 86, 0.4705882353);
}
nav .navbar-brand.active {
  border-bottom: 1.5px solid;
  color: rgba(0, 0, 0, 0.9);
}
nav #offcanvasNavbar {
  max-width: 50%;
}
nav .nav {
  flex-wrap: nowrap;
}
nav .nav-link {
  color: rgba(0, 0, 0, 0.55);
  white-space: nowrap;
}
nav .nav-link:hover {
  background: rgba(200, 200, 200, 0.5);
  color: #0d6efd !important;
  border-bottom: 1.5px solid;
  margin-bottom: -1.5px;
}
nav .nav-item {
  padding: 0 0.5rem;
  margin-bottom: 0.25rem;
}
nav .nav-item.active > .nav-link {
  border-bottom: 1.5px solid;
  color: rgba(0, 0, 0, 0.9);
}
nav #newsList {
  max-height: 50vh;
  overflow-y: auto;
}
nav #noNews {
  pointer-events: none;
}
nav .new-news-count,
nav .news-count {
  position: absolute;
  top: 0;
  left: 0;
  transition: all 1s ease-out;
  opacity: 1;
  z-index: 1030;
}
nav .news-item {
  padding: 0;
  background-color: rgba(200, 200, 200, 0.2);
}
nav .news-item:hover {
  background-color: rgb(120, 180, 255);
}
nav .news-item a {
  display: block;
  padding: 0.25rem 1rem 0rem 1rem;
}
nav .news-item p {
  color: #666;
  text-align: right;
  font-size: 0.8rem;
  margin: 0;
  padding: 0rem 1rem 0.25rem 1rem;
}
nav .transition-bg {
  transition: background-color 3s ease-in-out;
}
nav #confirm-news-title + .news-item .news-item-content,
nav [data-my-hr=confirm-news-hr] + .news-item .news-item-content {
  color: #666;
}
nav .dropdown-menu {
  width: 45vw;
  scroll-behavior: smooth;
}

@media (max-width: 575.9px) {
  .nav .dropdown-menu {
    width: 60vw;
    scroll-behavior: smooth;
  }
