/*
  與「分頁」有關的樣式
*/
.pagination {
  margin: 0;
  justify-content: center;
}

ul[data-pagination] .page-link {
  border-radius: 0 !important;
}

.page-link.pe-none {
  opacity: 0.5;
}

.pane-loading {
  position: relative;
  cursor: none;
  pointer-events: none;
}
